    def parse_pattern(pattern):
        components = []
        i = 0
        while i < len(pattern):
            if pattern[i] == 'p':
                start = i
                while i < len(pattern) and pattern[i] != 'q':
                    i += 1
                if i < len(pattern):
                    components.append(pattern[start:i+1])
                    i += 1
            else:
                i += 1
        return components

    def execute_pattern(pattern, depth):
        if pattern[0] == 'p':
            return depth
        elif pattern[0] == 'P':
            pattern_id = int(pattern[1:-1])
            return execute_pattern(patterns[pattern_id], depth + 1)
        else:
            return depth

    def find_infinite_loops(patterns):
        visited = set()
        for pattern in patterns:
            if pattern[0] == 'p':
                stack = [pattern]
                while stack:
                    current = stack.pop()
                    if current in visited:
                        return True
                    visited.add(current)
                    if current[0] == 'p':
                        start = 1
                        while start < len(current) and current[start] != 'q':
                            start += 1
                        if start < len(current):
                            stack.extend(current[start+1:-1].split('P'))
        return False

    patterns = parse_pattern(pattern)
    if find_infinite_loops(patterns):
        return [0, 0]
    else:
        depths = [execute_pattern(pattern, 0) for pattern in patterns]
        return [min(depths), max(depths)]
