def find_spec_prod_part(n, com):
    if is_prime(n):
        return "It is a prime number"

    partitions = []
    def find_partitions(n, current_partition):
        if n == 1:
            partitions.append(current_partition[:])
            return
        for i in range(2, n + 1):
            if n % i == 0:
                current_partition.append(i)
                find_partitions(n // i, current_partition)
                current_partition.pop()

    find_partitions(n, [])

    max_partition = None
    min_partition = None
    max_score = float('-inf')
    min_score = float('inf')

    for partition in partitions:
        score = calculate_score(partition)
        if score > max_score:
            max_score = score
            max_partition = partition
        if score < min_score:
            min_score = score
            min_partition = partition

    if com == 'max':
        return [max_partition, max_score]
    elif com == 'min':
        return [min_partition, min_score]
    else:
        return "Invalid command"
