def converter(n, decimals=0, base=3.14159):
    def convert_to_base(number, base):
        if number == 0:
            return "0"
        digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        result = ""
        is_negative = number < 0
        number = abs(number)
        while number > 0:
            remainder = int(number % base)
            result = digits[remainder] + result
            number /= base
        if is_negative:
            result = "-" + result
        return result

    def format_result(result, decimals):
        if '.' in result:
            integer_part, decimal_part = result.split('.')
            if len(decimal_part) < decimals:
                decimal_part += '0' * (decimals - len(decimal_part))
            elif len(decimal_part) > decimals:
                decimal_part = decimal_part[:decimals]
            result = f"{integer_part}.{decimal_part}"
        else:
            result += '.0' * decimals
        return result

    base_result = convert_to_base(n, base)
    formatted_result = format_result(base_result, decimals)
    return formatted_result
